<?php
if (realpath($_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__) {
    http_response_code(404);
    exit;
}
if (!isset($pdo)) { header('Location: /recipe/member/index.php'); exit; }
if (!$currentUser) { header('Location: /recipe/login.php'); exit; }
$tab = is_string($_GET['tab'] ?? null) ? $_GET['tab'] : 'profile';
$tabs=['profile'=>'Hồ sơ cá nhân','favorites'=>'Món yêu thích','recipes'=>'Công thức của tôi','history'=>'Lịch sử xem'];
if (!isset($tabs[$tab])) $tab='profile';
$stmt=$pdo->prepare('SELECT * FROM user_profiles WHERE user_id=?');$stmt->execute([$currentUser['id']]);
$profile=$stmt->fetch() ?: ['display_name'=>$currentUser['username'],'email'=>'','bio'=>''];
$flash=$_SESSION['community_flash'] ?? '';unset($_SESSION['community_flash']);
$items=[];
if ($tab==='favorites') {
    $stmt=$pdo->prepare('SELECT r.*,c.name AS category_name FROM favorites f JOIN recipes r ON r.id=f.recipe_id JOIN categories c ON c.id=r.category_id WHERE f.user_id=? AND (r.status=\'approved\' OR r.owner_id=f.user_id) ORDER BY f.created_at DESC,r.id DESC');
} elseif ($tab==='history') {
    $stmt=$pdo->prepare('SELECT r.*,c.name AS category_name,v.last_viewed_at FROM recipe_views v JOIN recipes r ON r.id=v.recipe_id JOIN categories c ON c.id=r.category_id WHERE v.user_id=? AND (r.status=\'approved\' OR r.owner_id=v.user_id) ORDER BY v.last_viewed_at DESC LIMIT 50');
} elseif ($tab==='recipes') {
    $stmt=$pdo->prepare('SELECT r.*,c.name AS category_name FROM recipes r JOIN categories c ON c.id=r.category_id WHERE r.owner_id=? ORDER BY r.created_at DESC,r.id DESC');
}
if ($tab!=='profile') { $stmt->execute([$currentUser['id']]);$items=$stmt->fetchAll(); }
?>
