<main class="wrap layout"><nav class="sidebar" aria-label="Tài khoản"><?php foreach($tabs as $key=>$label): ?><a class="<?= $key===$tab?'active':'' ?>" href="/recipe/member/index.php?tab=<?= e($key) ?>"><?= e($label) ?></a><?php endforeach; ?><a class="new" href="/recipe/member/create.php">+ Đăng công thức</a><a href="index.php">← Về trang chủ</a><?php if($currentAdmin): ?><a href="admin/index.php">Quản trị hệ thống</a><?php endif; ?></nav><section><h1><?= e($tabs[$tab]) ?></h1><?php if($flash): ?><p class="notice" role="status"><?= e($flash) ?></p><?php endif; ?>
<?php if($tab==='profile'): ?><div class="panel"><form method="post" action="/recipe/member/action.php"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="action" value="profile"><p class="hint">Tên đăng nhập: <?= e($currentUser['username']) ?>. Email hồ sơ chỉ hiển thị cho bạn.</p><label for="display_name">Tên hiển thị</label><input id="display_name" name="display_name" maxlength="80" required value="<?= e($profile['display_name']) ?>"><label for="email">Email liên hệ (không bắt buộc)</label><input type="email" id="email" name="email" maxlength="254" value="<?= e($profile['email']) ?>"><label for="bio">Giới thiệu bản thân</label><textarea id="bio" name="bio" rows="3" maxlength="500"><?= e($profile['bio']) ?></textarea><details><summary>Đổi mật khẩu</summary><p class="hint">Để trống nếu không đổi mật khẩu.</p><label for="current_password">Mật khẩu hiện tại</label><input type="password" id="current_password" name="current_password" autocomplete="current-password"><div class="row"><div><label for="new_password">Mật khẩu mới</label><input type="password" id="new_password" name="new_password" autocomplete="new-password" minlength="6"></div><div><label for="confirm_password">Nhập lại mật khẩu mới</label><input type="password" id="confirm_password" name="confirm_password" autocomplete="new-password" minlength="6"></div></div></details><p><button type="submit">Lưu hồ sơ</button></p></form></div>
<?php else: ?>
<?php if($tab==='history'): ?><p class="hint">Hiển thị tối đa 50 công thức gần nhất đã xem khi đăng nhập, mới nhất ở trên.</p><form method="post" action="/recipe/member/action.php" onsubmit="return confirm('Xóa lịch sử xem của bạn?')"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="action" value="clear_history"><button type="submit">Xóa lịch sử xem</button></form><br><?php endif; ?>
<?php if($tab==='recipes'): ?><p class="hint">Bạn được sửa hoặc xóa các công thức do chính tài khoản này đăng. Món mới hoặc nội dung được bạn sửa sẽ chờ quản trị duyệt trước khi hiển thị công khai. Công thức cũ chưa có tác giả vẫn do quản trị viên quản lý.</p><?php endif; ?>
<?php if(!$items): ?><div class="panel empty">Danh sách này chưa có công thức nào.<p><a href="index.php#cong-thuc">Khám phá món ngon →</a></p></div><?php else: ?><div class="list"><?php foreach($items as $item): ?><article class="item"><a href="recipe.php?id=<?= (int)$item['id'] ?>"><img src="<?= e($item['image_path'] ?: 'images/bua-com-nha.png') ?>" alt="<?= e($item['title']) ?>" loading="lazy"></a><div><h2><a href="recipe.php?id=<?= (int)$item['id'] ?>"><?= e($item['title']) ?></a></h2><p><?= e($item['category_name']) ?> · <?= (int)$item['cooking_minutes'] ?> phút</p><?php if($tab==='recipes'): ?><p><strong><?= e(recipeStatusLabels()[$item['status']] ?? $item['status']) ?></strong><?php if($item['review_note']): ?> — <?= e($item['review_note']) ?><?php endif; ?></p><?php endif; ?><?php if($tab==='history'): ?><p>Xem gần nhất: <?= e($item['last_viewed_at']) ?> UTC</p><?php endif; ?><div class="links"><a href="recipe.php?id=<?= (int)$item['id'] ?>">Xem công thức</a><?php if($tab==='recipes'): ?><a href="/recipe/member/edit.php?id=<?= (int)$item['id'] ?>">Sửa</a><a class="danger" href="/recipe/member/delete.php?id=<?= (int)$item['id'] ?>">Xóa</a><?php endif; ?><?php if($tab==='favorites'): ?><form method="post" action="/recipe/member/action.php"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="action" value="favorite"><input type="hidden" name="recipe_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="saved" value="0"><button type="submit">Bỏ lưu</button></form><?php endif; ?></div></div></article><?php endforeach; ?></div><?php endif; ?>
<?php endif; ?></section></main><footer>Bếp Nhà · Công thức nhỏ, thương nhớ đong đầy</footer></body></html>
